// ─── Painted clearing floors (art override) ─────────────────────────────────
//
// A painted top-down ground per terrain layout (PAINTED_FLOORS, generated by
// tools/arena-floors/make-floors.mjs) replaces the procedural floor fill +
// grass patches + decor scatter of the 'default' arena type. The painting is
// CLIPPED to the layout's own outline (traceArenaPath — the same SDF outline
// the physics uses), so the shape is exact whatever the painting; the wooden
// rim, the feature sprites and the towers still draw on top, so gameplay
// readability is unchanged. Drawn once into the static arena buffer.
//
// Procedural fallback (returns false):
//  - before the layout's WebP has loaded (lazy, per layout — the first call
//    starts the load; the static bake is re-keyed on floorArtRevision());
//  - when the bake would upscale the painting more than MAX_FLOOR_UPSCALE
//    (render-sharpness rule: never draw noticeably below css × dpr);
//  - with `?art=procedural` (A/B), in jsdom / node.
import { traceArenaPath, type ArenaShape } from '@/use/arenaShapes'
import { PAINTED_FLOORS } from '@/use/paintedFloors'
import { prependBaseUrl } from '@/utils/function'

type Ctx = CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D

/** Above this upscale the procedural floor (vector, always sharp) is drawn. */
export const MAX_FLOOR_UPSCALE = 1.5

let revision = 0
/** Bumps when a painted floor becomes available — key the static bake on it. */
export const floorArtRevision = (): number => revision

const images = new Map<number, HTMLImageElement | null>()

const artAllowed = (): boolean => {
  if (typeof Image === 'undefined' || typeof location === 'undefined') return false
  if (typeof navigator !== 'undefined' && /jsdom/i.test(navigator.userAgent)) return false
  return !/[?&]art=procedural(?:&|$)/.test(location.search)
}

/** Start loading a layout's painted floor (no-op when none / already asked). */
export const preloadFloorArt = (layoutId: number): void => {
  const meta = PAINTED_FLOORS[layoutId]
  if (!meta || images.has(layoutId) || !artAllowed()) return
  images.set(layoutId, null)
  const img = new Image()
  img.decoding = 'async'
  img.onload = () => {
    images.set(layoutId, img)
    revision++
  }
  img.src = prependBaseUrl(`images/arena-floors/${meta.file}?v=${meta.v}`)
}

/**
 * Draw the painted floor of `layoutId` clipped to the clearing (caller has
 * translated to the arena origin, scaled to arena units). Returns false when
 * the caller should draw its procedural floor instead.
 */
export const drawPaintedFloor = (ctx: Ctx, layoutId: number, shape: ArenaShape, R: number): boolean => {
  const meta = PAINTED_FLOORS[layoutId]
  if (!meta) return false
  preloadFloorArt(layoutId)
  const img = images.get(layoutId)
  if (!img) return false
  const t = ctx.getTransform()
  const deviceScale = Math.hypot(t.a, t.b) || 1
  if (2 * R * deviceScale > meta.size * MAX_FLOOR_UPSCALE) return false
  ctx.save()
  traceArenaPath(ctx, shape, R)
  ctx.clip()
  ctx.drawImage(img, -R, -R, 2 * R, 2 * R)
  // A flat, darker band just inside the wall grounds the rim (no gradient).
  ctx.strokeStyle = 'rgba(28, 52, 20, 0.16)'
  ctx.lineWidth = 18
  ctx.lineJoin = 'round'
  traceArenaPath(ctx, shape, R)
  ctx.stroke()
  ctx.restore()
  return true
}
